(()=>{function values(){return data.filmMixLevels??={original:100,music:100,effects:100};}const names={original:'对白与视频原声',music:'背景音乐与歌曲',effects:'环境音与音效'};function draw(){if(tab!==5)return;const v=values(),box=document.createElement('div');box.className='card';box.style.marginBottom='20px';box.innerHTML='<h3>合成音量</h3><p class="subtle">100% 沿用各分镜音量，向右调大，0% 为静音。设置只影响新合成的成片。</p><div class="film-volume-row">'+Object.entries(names).map(([k,n])=>'<label style="display:block;margin:0;min-width:0">'+n+' <b data-film-volume-label="'+k+'">'+v[k]+'%</b><input type="range" data-film-volume="'+k+'" min="0" max="200" step="5" value="'+v[k]+'" style="display:block;width:100%;max-width:540px;accent-color:#abdbc7"></label>').join('')+'</div><button id="resetFilmVolume" style="margin-top:14px">恢复100%</button>';const anchor=document.querySelector('#filmTransitions')||document.querySelector('#panel .card');anchor?.before(box);box.querySelectorAll('[data-film-volume]').forEach(el=>el.oninput=()=>{v[el.dataset.filmVolume]=Number(el.value);box.querySelector('[data-film-volume-label='+el.dataset.filmVolume+']').textContent=el.value+'%';save();});box.querySelector('#resetFilmVolume').onclick=()=>{Object.assign(v,{original:100,music:100,effects:100});save();stage();};}const oldStage=stage;stage=function(){oldStage();draw();};const oldFetch=frontFetch;frontFetch=async function(url,body){if(url==='/api/film-export'&&body?.items)body={...body,mix_levels:{...values()}};return oldFetch(url,body);};render();})();

(()=>{const style=document.createElement('style');style.textContent='.film-volume-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;align-items:center}.film-volume-row input[type=range]{max-width:none!important;margin:12px 0 0!important}@media(max-width:600px){.film-volume-row{grid-template-columns:minmax(0,1fr);gap:18px}}';document.head.append(style);})();
